// Adapted behavior from source prototype-v24.ts renderLayers; no source assets or private records.
export function attachNativeLayers({host,signal,onSelect,onVisible,onPin,onOrder}){
 const doc=host.ownerDocument;let disposed=false,records=new Map();
 host.innerHTML='<h2>Room layers</h2><p>All authored instances, including hidden and filtered objects. Groups follow native surfaces, not original left/right worlds. Pin is a native position pin, not the original lock. Visibility and layer-step edits explicitly adopt format v7 when needed. Raise/lower adjusts the numeric layer by one; equal layers retain normal paint order, not a forced swap.</p><div data-layer-groups></div><p data-layer-status role="status"></p>';
 const groups=host.querySelector('[data-layer-groups]'),status=host.querySelector('[data-layer-status]');
 function update(rows,selected){if(disposed||signal.aborted)return;records=new Map(rows.map(r=>[r.id,r]));groups.replaceChildren();if(!rows.length){status.textContent='Room has no object instances.';return;}status.textContent=`${rows.length} instances; selection does not change saved state.`;const sections=new Map();for(const row of [...rows].sort((a,b)=>b.zIndex-a.zIndex||(a.id<b.id?-1:a.id>b.id?1:0))){const key=row.scope==='sticker'?'Sticker: '+row.anchor:row.scope==='ui'?'Foundry UI':'World scene';let list=sections.get(key);if(!list){const section=doc.createElement('section'),heading=doc.createElement('h3');heading.textContent=key;list=doc.createElement('ul');section.append(heading,list);groups.append(section);sections.set(key,list);}const item=doc.createElement('li');item.dataset.layerId=row.id;const description=doc.createElement('p');description.textContent=`${row.name} · ${row.id} · stack ${row.zIndex}${row.unavailable?' · anchor unavailable':''}${row.filtered?' · filtered from scene':''}`;item.append(description);for(const [action,label,pressed]of [['select','Select instance',row.id===selected],['visible',row.visible?'Hide instance':'Show instance',row.visible],['pin',row.pinned?'Unpin position':'Pin position',row.pinned],['raise','Raise one layer',null],['lower','Lower one layer',null]]){const button=doc.createElement('button');button.type='button';button.dataset.layerAction=action;button.textContent=label;if(pressed!==null)button.setAttribute('aria-pressed',String(pressed));if(action==='raise')button.disabled=row.zIndex>=100000;if(action==='lower')button.disabled=row.zIndex<=0;item.append(button);}list.append(item);}}
 function click(event){if(disposed||signal.aborted)return;const button=event.target.closest?.('[data-layer-action]'),item=button?.closest('[data-layer-id]');if(!item||!host.contains(item))return;const row=records.get(item.dataset.layerId);if(!row)return;try{if(button.dataset.layerAction==='select')onSelect(row.id);else if(button.dataset.layerAction==='visible')onVisible(row.id,!row.visible);else if(button.dataset.layerAction==='pin')onPin(row.id,!row.pinned);else if(button.dataset.layerAction==='raise')onOrder(row.id,1);else if(button.dataset.layerAction==='lower')onOrder(row.id,-1);}catch{status.textContent='Layer action failed; inspect the current workspace before retrying.';}}
 host.addEventListener('click',click);function dispose(){if(disposed)return;disposed=true;records.clear();host.removeEventListener('click',click);signal.removeEventListener('abort',dispose);groups.replaceChildren();}signal.addEventListener('abort',dispose,{once:true});return{update,dispose};
}
